"use client"

import { useCallback, useRef, useState } from "react"

import "./tybow-motion.css"

import { ArrowButton } from "@/components/tybow/arrow-button"
import { MediaStack } from "@/components/tybow/flush-photo"
import { cn } from "@/lib/utils"

export type LooksCarouselSlide = {
  name: string
  tag: string
  photo: { src?: string; alt: string }
}

export type LooksCarouselProps = {
  id?: string
  eyebrow: string
  title: string
  copy: string
  cta?: { href: string; label: string }
  slides: LooksCarouselSlide[]
}

export function LooksCarousel({
  id,
  eyebrow,
  title,
  copy,
  cta,
  slides,
}: LooksCarouselProps) {
  const [on, setOn] = useState(0)
  const picksRef = useRef<HTMLDivElement>(null)
  const current = slides[on]

  const paint = useCallback(
    (index: number, scroll = false) => {
      if (!slides.length) return
      const next = (index + slides.length) % slides.length
      setOn(next)
      if (!scroll) return
      const picks = picksRef.current
      const active = picks?.children[next] as HTMLElement | undefined
      if (!picks || !active) return
      const target = active.offsetLeft - (picks.clientWidth - active.offsetWidth) / 2
      if (typeof picks.scrollTo === "function") {
        picks.scrollTo({ left: Math.max(0, target) })
      } else {
        picks.scrollLeft = Math.max(0, target)
      }
    },
    [slides.length],
  )

  return (
    <section id={id} className="bg-background py-section">
      <div className="px-[7vw]">
        <p className="text-[0.7rem] font-medium tracking-[0.26em] text-primary uppercase">
          {eyebrow}
        </p>
        <h2 className="mt-4 max-w-[16ch] font-display text-[length:clamp(1.85rem,3.2vw,3rem)] font-light tracking-[0.055em] text-foreground uppercase">
          {title}
        </h2>
        <p className="mt-5 max-w-[36rem] text-pretty text-foreground">{copy}</p>
        {cta ? (
          <p className="mt-8">
            <ArrowButton href={cta.href} variant="inverse">
              {cta.label}
            </ArrowButton>
          </p>
        ) : null}
      </div>

      <div className="mt-10 grid gap-3 px-[7vw]">
        <MediaStack
          frames={slides.map((slide) => slide.photo)}
          on={on}
          slideClassName="tybow-look-slide"
          className="aspect-[16/9] min-h-[14rem] outline outline-border -outline-offset-px md:min-h-[22rem]"
        />
        {current ? (
          <div className="flex min-h-[1.8rem] flex-wrap items-baseline justify-between gap-x-5 gap-y-1">
            <p className="font-display text-[length:clamp(1.45rem,2.2vw,1.9rem)] font-medium tracking-[-0.02em] text-foreground">
              {current.name}
            </p>
            <p className="text-[0.66rem] font-semibold tracking-[0.12em] text-muted-foreground uppercase">
              {current.tag}
            </p>
          </div>
        ) : null}
        <div
          ref={picksRef}
          className="grid grid-cols-2 gap-2 overflow-x-auto pb-4 md:flex md:grid-cols-none md:gap-2 lg:grid lg:grid-cols-6 lg:overflow-visible"
          role="tablist"
          aria-label="Looks"
          onKeyDown={(event) => {
            if (
              event.key !== "ArrowDown" &&
              event.key !== "ArrowUp" &&
              event.key !== "ArrowRight" &&
              event.key !== "ArrowLeft"
            ) {
              return
            }
            event.preventDefault()
            const dir =
              event.key === "ArrowDown" || event.key === "ArrowRight" ? 1 : -1
            const next = (on + dir + slides.length) % slides.length
            paint(next, true)
            const child = picksRef.current?.children[next] as HTMLElement | undefined
            child?.focus()
          }}
        >
          {slides.map((slide, index) => {
            const selected = index === on
            return (
              <button
                key={slide.name}
                type="button"
                role="tab"
                aria-selected={selected}
                aria-label={`${slide.name}, ${slide.tag}`}
                tabIndex={selected ? 0 : -1}
                className={cn(
                  "flex min-h-11 shrink-0 flex-col border bg-card text-left transition-[border-color,transform,box-shadow] duration-150 ease-[cubic-bezier(0.2,0,0,1)] md:w-[7.75rem] md:snap-start lg:w-auto",
                  selected ? "border-primary" : "border-border hover:border-primary",
                  "active:scale-[0.96]",
                )}
                onClick={() => paint(index, true)}
              >
                <span className="relative block aspect-[16/10] overflow-hidden bg-muted outline outline-border -outline-offset-px">
                  {slide.photo.src ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                      src={slide.photo.src}
                      alt=""
                      decoding="async"
                      className="absolute inset-0 size-full object-cover"
                      style={{ objectPosition: "50% 40%" }}
                    />
                  ) : null}
                  {selected ? (
                    <span className="absolute inset-0 outline-2 outline-offset-2 outline-primary" />
                  ) : null}
                </span>
                <span className="px-2 pt-1.5 font-display text-[0.95rem] font-medium tracking-[-0.02em] text-foreground">
                  {slide.name}
                </span>
                <span className="px-2 pt-0.5 pb-2 text-[0.58rem] leading-[1.3] tracking-[0.06em] text-muted-foreground uppercase">
                  {slide.tag}
                </span>
              </button>
            )
          })}
        </div>
      </div>
    </section>
  )
}

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@/lib/utils"

function ArrowIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M3 8h10M9 4l4 4-4 4"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="square"
      />
    </svg>
  )
}

export type ArrowButtonProps = {
  variant?: "cream" | "inverse" | "ghost"
  href?: string
  className?: string
  children: ReactNode
} & Omit<ComponentProps<"button">, "className">

export function ArrowButton({
  variant = "cream",
  href,
  className,
  children,
  type = "button",
  ...props
}: ArrowButtonProps) {
  const classes = cn(
    "inline-flex min-h-[3.25rem] items-center gap-3 pr-1.5 pl-5 font-sans text-[0.92rem] font-semibold tracking-[0.04em] uppercase",
    variant === "cream" &&
      "bg-primary-foreground text-foreground shadow-[0_10px_28px_color-mix(in_oklch,var(--foreground)_32%,transparent)] hover:bg-white",
    variant === "inverse" && "bg-primary text-primary-foreground hover:brightness-90",
    variant === "ghost" &&
      "min-h-[3.25rem] border-[1.5px] border-primary-foreground bg-foreground/60 px-5 text-primary-foreground hover:border-white hover:bg-foreground/80",
    className,
  )

  const iconWrap =
    variant === "ghost" ? null : (
      <span
        className={cn(
          "grid size-9 place-items-center",
          variant === "cream" && "bg-primary text-primary-foreground",
          variant === "inverse" && "bg-primary-foreground text-primary",
        )}
      >
        <ArrowIcon />
      </span>
    )

  const inner = (
    <>
      {children}
      {iconWrap}
    </>
  )

  if (href) {
    return (
      <a href={href} className={classes}>
        {inner}
      </a>
    )
  }

  return (
    <button type={type} className={classes} {...props}>
      {inner}
    </button>
  )
}

import { cn } from "@/lib/utils"

export type FlushPhotoProps = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
  className?: string
}

export type MediaFrame = { src?: string; alt: string }

export function MediaStack({
  frames,
  on,
  slideClassName,
  className,
  objectPosition,
}: {
  frames: MediaFrame[]
  on: number
  slideClassName: string
  className?: string
  objectPosition?: string
}) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {frames.map((frame, index) =>
        frame.src ? (
          // Parent owns crop. Animation classes must land on the img.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={`${frame.src}-${index}`}
            src={frame.src}
            alt={index === on ? frame.alt : ""}
            decoding="async"
            className={cn(slideClassName, index === on && "is-on")}
            style={objectPosition ? { objectPosition } : undefined}
          />
        ) : (
          <div
            key={`${frame.alt}-${index}`}
            className={cn(
              slideClassName,
              index === on && "is-on",
              "flex items-center justify-center bg-muted",
            )}
            role="img"
            aria-label={frame.alt}
          />
        ),
      )}
    </div>
  )
}

export function FlushPhoto({
  src,
  alt,
  label = "replace with client photo",
  fit = "cover",
  className,
}: FlushPhotoProps) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {src ? (
        // Parent owns crop and radius. No inner mat.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className={cn(
            "absolute inset-0 size-full",
            fit === "contain" ? "object-contain" : "object-cover",
          )}
        />
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center bg-muted px-6 text-center"
          role="img"
          aria-label={alt}
        >
          <p className="text-sm text-muted-foreground">{label}</p>
        </div>
      )}
    </div>
  )
}

/* Motion ported from The Pines: wh-pines.css + wh-pe-brand.css.
   Token-only. Values (timings, easings, travel) stay literal. */

@keyframes tybow-pull {
  to {
    transform: none;
    opacity: 1;
  }
}

.tybow-pull {
  display: inline-block;
  transform: translateY(0.42em);
  opacity: 0;
  animation: tybow-pull 0.72s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc(var(--i, 0) * 90ms + 80ms);
}

.tybow-pull-late {
  transform: translateY(0.8rem);
  opacity: 0;
  animation: tybow-pull 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Ken Burns lives on the IMG, not a wrapper. */
.tybow-hero-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: 50% 52%;
  opacity: 0;
  transform: scale(1.02);
  transition:
    opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    transform 7s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.tybow-hero-slide.is-on {
  opacity: 1;
  transform: scale(1);
}

.tybow-look-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-look-slide.is-on {
  opacity: 1;
}

.tybow-overview-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-overview-slide.is-on {
  opacity: 1;
  z-index: 1;
}

.tybow-gallery {
  display: flex;
  flex-direction: row;
  gap: 1px;
  width: 100%;
  height: min(56vh, 32rem);
  min-height: 22rem;
  overflow: hidden;
  background: var(--foreground);
}

.tybow-gallery-item {
  position: relative;
  overflow: hidden;
  flex: 0.5 1 2.55rem;
  min-width: 2.45rem;
  height: 100%;
  padding: 0;
  border: 0;
  background: var(--foreground);
  cursor: pointer;
  text-align: left;
  line-height: 0;
  transition: flex-grow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-gallery-item.is-active {
  flex-grow: 16;
}

.tybow-gallery-item img,
.tybow-gallery-item .tybow-gallery-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
}

.tybow-gallery-item::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to right,
    color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
    color-mix(in oklch, var(--foreground) 62%, transparent) 55%,
    color-mix(in oklch, var(--foreground) 28%, transparent) 100%
  );
  opacity: 1;
  transition: opacity 0.3s ease;
}

.tybow-gallery-item.is-active::after {
  opacity: 0;
}

.tybow-gallery-spine {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 1;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  padding: 1.05rem 0.55rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  text-shadow: 0 1px 12px color-mix(in oklch, var(--foreground) 70%, transparent);
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.25s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-spine {
  opacity: 0;
}

.tybow-gallery-cap {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  padding: 2.6rem 1.2rem 1.05rem;
  background: linear-gradient(
    to top,
    color-mix(in oklch, var(--foreground) 70%, transparent),
    transparent
  );
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  pointer-events: none;
  opacity: 0;
  transform: translateY(0.5rem);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-cap {
  opacity: 1;
  transform: none;
}

.tybow-deck-card-body,
.tybow-deck-card::after {
  transition:
    opacity 420ms ease,
    transform 420ms ease;
}

.tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
  opacity: 0.55;
  transform: translateY(10px);
}

.tybow-spec-line {
  --pin-line-delay: 0ms;
}

.tybow-spec-line::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 1px;
  background: var(--border);
}

@media (prefers-reduced-motion: no-preference) {
  .tybow-spec .tybow-spec-line::after {
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 620ms cubic-bezier(0.23, 1, 0.32, 1)
      var(--pin-line-delay, 0ms);
  }

  .tybow-spec .tybow-spec-tick {
    opacity: 0;
    transform: translateX(-5px);
    transition:
      opacity 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms),
      transform 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms);
  }

  .tybow-spec.is-inview .tybow-spec-line::after {
    transform: scaleX(1);
  }

  .tybow-spec.is-inview .tybow-spec-tick {
    opacity: 1;
    transform: none;
  }

  .tybow-spec-line:nth-child(1) {
    --pin-line-delay: 300ms;
  }
  .tybow-spec-line:nth-child(2) {
    --pin-line-delay: 375ms;
  }
  .tybow-spec-line:nth-child(3) {
    --pin-line-delay: 450ms;
  }
  .tybow-spec-line:nth-child(4) {
    --pin-line-delay: 525ms;
  }
  .tybow-spec-line:nth-child(5) {
    --pin-line-delay: 600ms;
  }
  .tybow-spec-line:nth-child(6) {
    --pin-line-delay: 675ms;
  }
}

@media (max-width: 800px) {
  .tybow-gallery {
    height: auto;
    min-height: 0;
    flex-direction: column;
  }

  .tybow-gallery-item {
    flex: 0 0 2.65rem;
    width: 100%;
    min-width: 0;
    height: 2.65rem;
    transition:
      height 0.4s cubic-bezier(0.22, 1, 0.36, 1),
      flex-basis 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .tybow-gallery-item.is-active {
    flex: 0 0 22rem;
    height: 22rem;
  }

  .tybow-gallery-item::after {
    background: linear-gradient(
      to top,
      color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
      color-mix(in oklch, var(--foreground) 45%, transparent) 70%,
      transparent 100%
    );
  }

  .tybow-gallery-spine {
    writing-mode: horizontal-tb;
    transform: none;
    inset: auto auto 0.7rem 0.9rem;
    padding: 0;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
  }
}

@media (max-width: 959px) {
  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tybow-pull,
  .tybow-pull-late {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .tybow-hero-slide,
  .tybow-hero-slide.is-on,
  .tybow-look-slide,
  .tybow-overview-slide,
  .tybow-gallery-item,
  .tybow-gallery-item::after,
  .tybow-gallery-spine,
  .tybow-gallery-cap,
  .tybow-deck-card-body,
  .tybow-deck-card::after {
    transition: none;
    transform: none;
  }

  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}
